package cn.vie.vibe.gallery.infrastructure;
import cn.vie.vibe.gallery.application.*; import cn.vie.vibe.gallery.domain.*; import java.time.Instant; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Component; import java.time.Duration; import java.net.URI; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
@Profile("dev-memory")
@Component class DevObjectStorage implements ObjectStoragePort { private final Map<String,byte[]> objects=new ConcurrentHashMap<>(); public StoredObject put(String key,java.io.InputStream in,String type,long size){try{objects.put(key,in.readAllBytes());return new StoredObject("memory",key,null,size,null,null,"");}catch(java.io.IOException e){throw new IllegalStateException(e);}} public java.io.InputStream get(String key){byte[] content=objects.get(key);if(content==null)throw new IllegalStateException("Object not found: "+key);return new java.io.ByteArrayInputStream(content);} public void delete(String key){objects.remove(key);} public URI createReadUrl(String key,Duration ttl){return URI.create("memory:///"+key);} public URI createReadUrl(String key){return URI.create("memory:///"+key);} }
@Profile("dev-memory")
@Component class DevGalleryLookup implements GalleryLookup { public Optional<Gallery> findById(UUID t,UUID g){return Optional.of(new Gallery(g,t,"dev","Dev",GalleryVisibility.PRIVATE,null,null,false,java.time.Instant.now(),GalleryStatus.PUBLISHED,java.time.Instant.now()));} }
@Profile("dev-memory") @Component class DevPhotoRepository implements PhotoRepository { final Map<UUID,Photo> m=new ConcurrentHashMap<>(); private java.util.stream.Stream<Photo> publicReady(UUID t,UUID g){return m.values().stream().filter(p->p.tenantId().equals(t)&&p.galleryId().equals(g)&&p.status()==PhotoStatus.READY).sorted(java.util.Comparator.comparingInt(Photo::sortOrder).thenComparing(Photo::createdAt).thenComparing(Photo::id));} public Photo save(Photo p){m.put(p.id(),p);return p;} public List<Photo> findByGallery(UUID t,UUID g){return m.values().stream().filter(p->p.tenantId().equals(t)&&p.galleryId().equals(g)&&p.status()!=PhotoStatus.DELETED).sorted(java.util.Comparator.comparingInt(Photo::sortOrder).thenComparing(Photo::createdAt).thenComparing(Photo::id)).toList();} public List<Photo> findByGalleryIdWithPagination(UUID g,int o,int l){return m.values().stream().filter(p->p.galleryId().equals(g)&&p.status()!=PhotoStatus.DELETED).sorted(java.util.Comparator.comparingInt(Photo::sortOrder).thenComparing(Photo::createdAt).thenComparing(Photo::id)).skip(o).limit(l).toList();} public int countByGalleryId(UUID g){return (int)m.values().stream().filter(p->p.galleryId().equals(g)&&p.status()!=PhotoStatus.DELETED).count();} public List<Photo> findPublicReadyByGalleryId(UUID t,UUID g,int o,int l){return publicReady(t,g).skip(o).limit(l).toList();} public int countPublicReadyByGalleryId(UUID t,UUID g){return (int)publicReady(t,g).count();} public int countFailedByGalleryId(UUID t,UUID g){return (int)m.values().stream().filter(p->p.tenantId().equals(t)&&p.galleryId().equals(g)&&p.status()==PhotoStatus.FAILED).count();} public Optional<Photo> findById(UUID t,UUID id){return Optional.ofNullable(m.get(id)).filter(p->p.tenantId().equals(t)&&p.status()!=PhotoStatus.DELETED);} public Optional<Photo> findById(UUID id){return Optional.ofNullable(m.get(id)).filter(p->p.status()!=PhotoStatus.DELETED);} public int updateStatus(UUID t,UUID id,PhotoStatus s){return findById(t,id).map(p->{m.put(id,new Photo(p.id(),p.tenantId(),p.galleryId(),p.storageObjectId(),p.title(),p.sortOrder(),p.cover(),s,p.createdAt()));return 1;}).orElse(0);} public int updateMetadata(UUID t,UUID id,String a,Integer b,Boolean c){return findById(t,id).map(p->{m.put(id,new Photo(p.id(),p.tenantId(),p.galleryId(),p.storageObjectId(),a==null?p.title():a,b==null?p.sortOrder():b,c==null?p.cover():c,p.status(),p.createdAt()));return 1;}).orElse(0);} public int clearCoverByGallery(UUID t,UUID g){m.values().stream().filter(p->p.tenantId().equals(t)&&p.galleryId().equals(g)&&p.cover()).forEach(p->m.put(p.id(),new Photo(p.id(),p.tenantId(),p.galleryId(),p.storageObjectId(),p.title(),p.sortOrder(),false,p.status(),p.createdAt())));return 1;} public int softDelete(UUID t,UUID id){return updateStatus(t,id,PhotoStatus.DELETED);} }
@Profile("dev-memory") @Component class DevStorageObjectRepository implements StorageObjectRepository { final Map<UUID,StorageObject> m=new ConcurrentHashMap<>(); public StorageObject save(StorageObject x){m.put(x.id(),x);return x;} public Optional<StorageObject> findById(UUID t,UUID i){return Optional.ofNullable(m.get(i)).filter(x->x.tenantId().equals(t)&&x.status()!=StorageObjectStatus.DELETED);} public int markReady(UUID t,UUID i,String k,Integer w,Integer h){return update(t,i,x->new StorageObject(x.id(),x.tenantId(),x.bucket(),x.objectKey(),k,x.mimeType(),x.byteSize(),w,h,x.sha256(),StorageObjectStatus.READY,x.createdAt()));} public int markFailed(UUID t,UUID i){return update(t,i,x->new StorageObject(x.id(),x.tenantId(),x.bucket(),x.objectKey(),x.thumbnailKey(),x.mimeType(),x.byteSize(),x.width(),x.height(),x.sha256(),StorageObjectStatus.FAILED,x.createdAt()));} public int softDelete(UUID t,UUID i){return update(t,i,x->new StorageObject(x.id(),x.tenantId(),x.bucket(),x.objectKey(),x.thumbnailKey(),x.mimeType(),x.byteSize(),x.width(),x.height(),x.sha256(),StorageObjectStatus.DELETED,x.createdAt()));} private int update(UUID t,UUID i,java.util.function.UnaryOperator<StorageObject> f){return Optional.ofNullable(m.get(i)).filter(x->x.tenantId().equals(t)).map(x->{m.put(i,f.apply(x));return 1;}).orElse(0);} }
@Profile("dev-memory") @Component class DevTaskRepository implements PhotoProcessingTaskRepository { final Map<UUID,PhotoProcessingTask> m=new ConcurrentHashMap<>(); public synchronized PhotoProcessingTask save(PhotoProcessingTask t){m.put(t.id(),t);return t;} public Optional<PhotoProcessingTask> findById(UUID tenant,UUID id){return Optional.ofNullable(m.get(id)).filter(t->t.tenantId().equals(tenant));} public Optional<PhotoProcessingTask> findByTenantAndIdempotencyKey(UUID tenant,String key){return m.values().stream().filter(t->t.tenantId().equals(tenant)&&key!=null&&key.equals(t.idempotencyKey())).findFirst();} public List<PhotoProcessingTask> findByGallery(UUID tenant,UUID gallery,TaskFilter filter,long offset,int limit){return m.values().stream().filter(t->t.tenantId().equals(tenant)&&t.galleryId()!=null&&t.galleryId().equals(gallery)&&filter.includes(t.status())).sorted(Comparator.comparing(PhotoProcessingTask::createdAt,Comparator.nullsLast(Comparator.reverseOrder()))).skip(offset).limit(limit).toList();} public long countByGallery(UUID tenant,UUID gallery,TaskFilter filter){return m.values().stream().filter(t->t.tenantId().equals(tenant)&&t.galleryId()!=null&&t.galleryId().equals(gallery)&&filter.includes(t.status())).count();} public TaskSummary summaryByGallery(UUID tenant,UUID gallery){return TaskSummary.from(m.values().stream().filter(t->t.tenantId().equals(tenant)&&t.galleryId()!=null&&t.galleryId().equals(gallery)).toList());} public synchronized Optional<PhotoProcessingTask> claimNext(){return m.values().stream().filter(t->t.status().normalized()==TaskStatus.QUEUED).findFirst().map(t->{PhotoProcessingTask claimed=new PhotoProcessingTask(t.id(),t.tenantId(),t.galleryId(),t.photoId(),t.filename(),TaskStatus.PROCESSING,t.progress(),t.stage(),t.attempts()+1,t.maxAttempts(),t.errorCode(),t.errorMessage(),t.requestId(),"dev-worker",t.nextAttemptAt(),Instant.now(),Instant.now(),t.startedAt()==null?Instant.now():t.startedAt(),t.finishedAt(),t.cancelledAt(),t.clientBatchId(),t.idempotencyKey(),t.createdAt(),Instant.now());m.put(t.id(),claimed);return claimed;});} public Optional<PhotoProcessingTask> claimNext(Instant now,String worker){return claimNext();} public int heartbeat(UUID tenant,UUID id,String worker,Instant now){return update(tenant,id,t->(t.status()==TaskStatus.PROCESSING||t.status()==TaskStatus.CANCEL_REQUESTED)&&worker.equals(t.workerId())?new PhotoProcessingTask(t.id(),t.tenantId(),t.galleryId(),t.photoId(),t.filename(),t.status(),t.progress(),t.stage(),t.attempts(),t.maxAttempts(),t.errorCode(),t.errorMessage(),t.requestId(),t.workerId(),t.nextAttemptAt(),t.lockedAt(),now,t.startedAt(),t.finishedAt(),t.cancelledAt(),t.clientBatchId(),t.idempotencyKey(),t.createdAt(),now):t);} public int progress(UUID tenant,UUID id,String worker,int progress,String stage,Instant now){return heartbeat(tenant,id,worker,now);} public int complete(UUID tenant,UUID id,String worker,Instant now){return update(tenant,id,t->t.status()==TaskStatus.PROCESSING&&worker.equals(t.workerId())?t.withStatus(TaskStatus.SUCCEEDED,now):t);} public int fail(UUID tenant,UUID id,String worker,String code,String message,String requestId,boolean terminal,Instant next,Instant now){return update(tenant,id,t->(t.status()==TaskStatus.PROCESSING||t.status()==TaskStatus.CANCEL_REQUESTED)&&worker.equals(t.workerId())?new PhotoProcessingTask(t.id(),t.tenantId(),t.galleryId(),t.photoId(),t.filename(),terminal?TaskStatus.FAILED:TaskStatus.QUEUED,t.progress(),t.stage(),t.attempts(),t.maxAttempts(),code,message,requestId,null,next,null,null,t.startedAt(),terminal?now:null,null,t.clientBatchId(),t.idempotencyKey(),t.createdAt(),now):t);} public int retry(UUID tenant,UUID id,Instant next,Instant now){return update(tenant,id,t->t.status()==TaskStatus.FAILED&&t.retryable()?new PhotoProcessingTask(t.id(),t.tenantId(),t.galleryId(),t.photoId(),t.filename(),TaskStatus.QUEUED,t.progress(),t.stage(),t.attempts(),t.maxAttempts(),null,null,null,null,next,null,null,t.startedAt(),null,null,t.clientBatchId(),t.idempotencyKey(),t.createdAt(),now):t);} public int requestCancel(UUID tenant,UUID id,Instant now){return update(tenant,id,t->t.status()==TaskStatus.PROCESSING?t.withStatus(TaskStatus.CANCEL_REQUESTED,now):t);} public int cancelQueued(UUID tenant,UUID id,Instant now){return update(tenant,id,t->t.status()==TaskStatus.QUEUED?t.withStatus(TaskStatus.CANCELLED,now):t);} public int recoverStale(Instant threshold,Instant now){return 0;} private int update(UUID tenant,UUID id,java.util.function.UnaryOperator<PhotoProcessingTask> f){PhotoProcessingTask current=m.get(id);if(current==null||!current.tenantId().equals(tenant))return 0;PhotoProcessingTask updated=f.apply(current);if(updated==current)return 0;m.put(id,updated);return 1;} }
@Profile("dev-memory") @Component class DevQuotaRepository implements TenantQuotaRepository { final Map<UUID,TenantQuota> m=new ConcurrentHashMap<>(); public TenantQuota findForUpdate(UUID t){return m.getOrDefault(t,new TenantQuota(t,5L*1024*1024*1024,0,10000,0));} public void ensure(UUID t,long b,long p){m.putIfAbsent(t,new TenantQuota(t,b,0,p,0));} public synchronized void reserve(UUID t,long b,long p){TenantQuota q=findForUpdate(t);if(q.usedBytes()+b>q.maxBytes()||q.photoCount()+p>q.maxPhotos())throw new DomainException("QUOTA_EXCEEDED","Quota exceeded");m.put(t,new TenantQuota(t,q.maxBytes(),q.usedBytes()+b,q.maxPhotos(),q.photoCount()+p));} public synchronized void release(UUID t,long b,long p){TenantQuota q=findForUpdate(t);m.put(t,new TenantQuota(t,q.maxBytes(),Math.max(0,q.usedBytes()-b),q.maxPhotos(),Math.max(0,q.photoCount()-p)));} }
@Profile("dev-memory") @Component class DevGalleryViewerConfigRepository implements GalleryViewerConfigRepository { final Map<UUID,GalleryViewerConfig> m=new ConcurrentHashMap<>(); public Optional<GalleryViewerConfig> findByGalleryId(UUID g){return Optional.ofNullable(m.get(g));} public void save(GalleryViewerConfig c){m.put(c.galleryId(),c);} public int deleteByGalleryId(UUID g){return m.remove(g)!=null?1:0;} }
